--
-- Table structure for table `t_route_detail`
--

DROP TABLE IF EXISTS `t_route_detail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_route_detail` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `routeId` bigint DEFAULT '0' COMMENT '路线id',
  `stationId` bigint DEFAULT '0' COMMENT '站点id',
  `speed` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '速度',
  `area` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '安全防护区域，业务/PLC字段',
  `direction` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '目标航向角，存储单位：度，发布 path_point 时转换为弧度',
  `stopTime` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '作业时长，单位：秒，对应 path_point 的相对字段 [8]',
  `createTime` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updateTime` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `isDelete` tinyint DEFAULT '0' COMMENT '是否删除',
  `action` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '站点动作编码，业务/PLC字段',
  `position` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '定位模式，对应 path_point 的相对字段 [6]，枚举以硬件协议为准',
  `stop` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '是否停车：0-不停车，1-停车，不进入 path_point 的相对字段 [8]',
  `runmode` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '运行模式：0-追踪，1-自转，对应 path_point 的相对字段 [5]',
  `lanechange` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '变道绕障：0-禁止，1-左，2-右，3-左右，不进入 path_point 的相对字段 [7] 预留字段',
  `direction_option` varchar(32) COLLATE utf8mb4_general_ci DEFAULT 'useAngle' COMMENT '方向选项: useAngle=使用角度, useNextPoint=指向下一点, keepDirection=保持原方向',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=12933 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='路线详情';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `t_route_detail`
--

LOCK TABLES `t_route_detail` WRITE;
/*!40000 ALTER TABLE `t_route_detail` DISABLE KEYS */;
